style.css:
/* Broly Global Wallpaper */
/* i really want this to be global */

:root {
    --my-image: url("https://i.postimg.cc/x1nTnw8c/broly-eyes-dragon-ball-hd-wallpaper-uhdpaper-com-85-5-o.jpg");
    --my-panel: rgba(0, 0, 0, 0.25);
}

/* Wallpaper do Broly */
html {
    background-image: var(--my-image) !important;
    background-position: center center !important;
    background-size: cover !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
    min-height: 100vh !important;
}

/* Fundos transparentes */
body, main, section, article {
    background: transparent !important;
}

/* Menus semitransparentes */
header, aside, nav, footer {
    background-color: var(--my-panel) !important;
}
